class Solution {
    private boolean vowel(char character){
        return "aeiou".indexOf(character)>=0;
    }
    public int[] vowelStrings(String[] words,int[][] queries){
        int[] prefix=new int[words.length+1];
        for(int i=0;i<words.length;i++)prefix[i+1]=prefix[i]+(vowel(words[i].charAt(0))&&vowel(words[i].charAt(words[i].length()-1))?1:0);
        int[] answer=new int[queries.length];
        for(int i=0;i<queries.length;i++)answer[i]=prefix[queries[i][1]+1]-prefix[queries[i][0]];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun vowelStrings(words:Array<String>,queries:Array<IntArray>):IntArray{
        fun vowel(character:Char):Boolean{
            return character in "aeiou"
        };
        val prefix=IntArray(words.size+1);
        for(i in words.indices)prefix[i+1]=prefix[i]+(if(vowel(words[i].first())&&vowel(words[i].last()))1 else 0);
        return IntArray(queries.size){
            prefix[queries[it][1]+1]-prefix[queries[it][0]]
        }
    }
}

